"""Migration of Meridian CRM 4.2 order_totals.crms."""

from decimal import Decimal, ROUND_HALF_UP, localcontext


_CENTS = Decimal("0.01")


def _numeric(value) -> Decimal:
    """Apply legacy NVL(x, 0) numeric behavior using exact decimal conversion."""
    if value is None or value == "":
        return Decimal(0)
    if isinstance(value, float):
        return Decimal(str(value))
    return Decimal(str(value))


def _round_cents(value: Decimal) -> Decimal:
    return value.quantize(_CENTS, rounding=ROUND_HALF_UP)


def recompute(order: dict, lines: list[dict]) -> tuple[dict, list[dict], list]:
    """Recompute live line extensions and the discounted order total."""
    new_order = order.copy()
    new_lines = [line.copy() for line in lines]

    # Legacy ORD_HEADER loop guard, including blank-as-N boolean convention.
    if order.get("DEL_FLG") == "Y" or order.get("STAT_CD") == "X":
        return new_order, new_lines, []

    numeric_values = [
        _numeric(order.get("DISC_PCT", "")),
        _numeric(order.get("TOT_AMT", "")),
    ]
    for line in lines:
        if line.get("DEL_FLG") != "Y":
            numeric_values.append(_numeric(line.get("QTY", "")))
            numeric_values.append(_numeric(line.get("UNIT_PRC", "")))

    # Ensure sufficient decimal precision for exact intermediate arithmetic before
    # applying the legacy half-up cents rounding.
    precision = max(
        50,
        sum(len(value.as_tuple().digits) for value in numeric_values)
        + len(lines)
        + 10,
    )

    with localcontext() as context:
        context.prec = precision

        total = Decimal(0)
        for source_line, result_line in zip(lines, new_lines):
            if source_line.get("DEL_FLG") == "Y":
                continue

            ext = _round_cents(
                _numeric(source_line.get("QTY", ""))
                * _numeric(source_line.get("UNIT_PRC", ""))
            )
            result_line["EXT_AMT"] = float(ext)
            total += ext

        discounted = _round_cents(
            total * (Decimal(100) - _numeric(order.get("DISC_PCT", "")))
            / Decimal(100)
        )

    audits = []
    if _numeric(order.get("TOT_AMT", "")) != discounted:
        new_order["TOT_AMT"] = float(discounted)
        audits.append(("ORD_RETOTAL", order.get("ORD_ID")))
    else:
        new_order["TOT_AMT"] = float(discounted)

    return new_order, new_lines, audits
